  ver: 'board-vela-1c3b-2026-10-27',
  conf0: 70, agmMin: 40, agmWarn: 50, agmFm: 3,                 // 정기 주총 = FY 종료 뒤 3번째 달(6월) 마감 직후(회계 월 3 = 7월 1일 00:00) · 4월 1일 경고(Q82)
