  axis: { growthTh: 0.03, cxHi: 65, cxLo: 50, morHi: 60, morLo: 50, safeHold: -2, cnlTh: 0.05, cnlV: -1, pctN: 3, pctHi: 0.75, pctLo: 0.25 },
  patienceExtra: -5,
