/* 193차 P1-a: 이 표의 한국어(정본)를 언어 층 사전 MG.T.dict.ko에 같은 키로 등록 — 엔진은 MG.M(키, 값)으로 저장, 화면은 MG.T.fmt · MG.tx = 화면용 문자열(종전 그대로) */
if (MG.T) { (function () { var o = {}; for (var k in MG.data.text.t) o[k] = MG.data.text.t[k].ko; o['log.ach.on.excl'] = o['log.ach.on.excl'].replace('{ids}', '{ids|join:·}'); MG.T.add('ko', o); })(); }
MG.tx = function (key, vars) {
  var e = MG.data.text && MG.data.text.t[key], s = e ? e.ko : key;
  if (vars) s = s.replace(/\{(\w+)\}/g, function (m, k) { return vars[k] != null ? String(vars[k]) : m; });
  return s;
};
