    var tz = D().airports[T.base].tz, ivs = [], nF = 0, nS = 0, n = 0, rk = {};
    C.rots.forEach(function (r) { if (r.reg === reg) rk[r.reg + '#' + (r.ver || 1)] = r; });
    for (var d = MG.tz.addDays(from, -1); d <= to; d = MG.tz.addDays(d, 1)) C.legs.forEach(function (L) {
      if (!rk[L.rk] || !legOn(C, L, d)) return; var dd = MG.tz.addDays(d, L.dayOffset), f = C.fl[L.id + ':' + dd];
      if (f) { if (f.tail === reg && f.state !== 'CNL') ivs.push([f.etd, f.eta]); return; }
      var u = MG.tz.toUTC(dd, L.stdLocal, D().airports[L.from].tz); if (!u.hold) ivs.push([u.t, u.t + L.block]);
    });
