  /* ---------- 업무량·표준(2-2 「표준 = 업무량 × 단가」) ---------- */
  function nTails(C) { var n = 0; for (var k in C.tails) { var s = C.tails[k].status; if (s !== 'delivery' && s !== 'returned') n++; } return n; }
