  function stdBudget(C, id) { var s = 0; for (var k in C.org.lines) { var L = C.org.lines[k]; if (L.dept === id) s += L.amt; } return Math.round(s * 12 * 1.05); }

  /* ---------- 출력 계수(2-2) ---------- */
  function fOf(cap) { var c = O().cap; return clamp(c.fLo, c.fHi, 1 + (cap - c.base) * (cap >= c.base ? c.fUp : c.fDn)); }
  function f(C, id) { if (!C.org || ctl(C)) return 1; var d = dept(C, id); return d && d.state === 'active' ? fOf(d.out) : 1; }
  function turnOf(C, type) { var t = BD().types[type].turn; return C.org && !ctl(C) ? Math.round(t * (2 - f(C, 'ops.occ'))) : t; }
  function crewCapF(C) { return f(C, 'ops.cockpit'); }
  function yrs(C) { return per(C, today(C)).fy - per(C, C.start).fy; }            // 기령 +1년 = 회계연도 시작마다(drift.age)
  function mxF(C, reg) { if (!C.org || ctl(C)) return 1; return Math.pow(1 + O().tech.ageMx * diffP(C).drift, yrs(C)); }
  function aMin(C, type) { var w = C.org && !ctl(C) ? dept(C, 'mx.line').pol.window : null; return w || BD().types[type].aCheckMin; }
  function techP(C, f0) {
    if (!C.org || ctl(C)) return 0;
    var o = O(), T = C.tails[f0.tail], age = (T && T.age0 || 0) + yrs(C);
    return o.tech.p0 * (2 - f(C, 'mx.line')) * (1 + o.tech.ageRel * age * diffP(C).drift) * (o.window[dept(C, 'mx.line').pol.window] || 1) * (diffP(C).dly || 1);   // 178차 D2: 기술 지연 배수(1번만 · 칸 없음 = 1.0)
  }
  // 출발 전 기술 지연(11.1 ② 앞 — BRD 전환 때 한 번, 사건 키 난수)
  function techCheck(C, fl) {
    var p = techP(C, fl); if (!p) return 0;
    if (MG.rand.r(C, 'tech', fl.id) >= p) return 0;
    var o = O().tech, m = o.minDelay + Math.floor(MG.rand.r(C, 'techm', fl.id) * (o.maxDelay - o.minDelay + 1));
    fl.etd += m; fl.eta = fl.etd + fl.block; fl.cause = MG.M('org.techCheck.2', { m: m });
    var s = stat(C, fl); s.tech++; s.techMin += m;
    log(C, MG.M('org.techCheck.1', { fn: fl.fn, m: m }), 'ev');
    return m;
  }
  function stat(C, fl) { var mk = per(C, MG.tz.local(fl.std, C.hqTz).date).mk; return C.org.stats[mk] || (C.org.stats[mk] = { tech: 0, techMin: 0, prop: 0, propMin: 0, mxHold: 0, swap: 0, crewHold: 0 }); }
  function onProp(C, fl, add) { if (!C.org) return; var s = stat(C, fl); s.prop++; s.propMin += add; }
