      var x = C.rots.filter(function (r) { return r.reg === reg && r.legs && r.legs.length && r.validFrom <= rd && (!r.validTo || r.validTo >= rd) && !(r.validTo && r.validTo < r.validFrom); })[0];
      if (!x || !x.dow || x.dow.length >= 7 || MG.ops.rotOn(C, x, rd)) return;
