    if (C.mxWindows.some(function (w) { return w.tail === S.reg && w.state !== 'done' && w.start < end && w.end > t; })) return MG.M('org.nextOwnWhy.4');
    var nx = nextOwnDep(C, S.reg, t);
    if (!nx) return last.to === S.base ? null : MG.M('org.nextOwnWhy.3', { to: last.to, base: S.base });
    if (nx[1] !== last.to) return MG.M('org.nextOwnWhy.2', { to: last.to, v: nx[1] });
    var need = end + turnOf(C, S.type) + (C.rots.filter(function (r) { return r.reg === S.reg; }).reduce(function (m, r) { return Math.max(m, r.slack || 0); }, 0));
    return need <= nx[0] ? null : MG.M('org.nextOwnWhy.1');
