    if (mode === 'fixed' && by !== 'test') return { ok: false, why: MG.M('org.setPolicy.8') };
    if (ctl(C) && by !== 'test') return { ok: false, why: MG.M('org.setPolicy.7') };
    var mi = curMi(C), cur = d.pol[pol], r;
    if (pol !== 'edu' && JSON.stringify(cur) === JSON.stringify(v)) return { ok: false, why: MG.M('org.setPolicy.6') };
