  /* ---------- 재무·자금: 차입(Obligation 원금·이자 회차) ---------- */
  function loanRate(C) { var o = O().loan; return Math.round((o.base - (f(C, 'fin.treasury') - 1) * o.capF / 0.16) * 10000) / 10000; }
