    var hp = dept(C, 'hr.people').pol.wage; if (!ctl(C)) C.org.wageIdx = hp;
    // ⑹ 실행 비용 줄 재산정(인원·임금 지수·서비스 수준) — 통제 모드는 개시 줄 그대로
    if (!ctl(C) && C.fin) for (var lid in C.org.lines) reprice(C, lid, lineAmt(C, lid), mi);
