      var a = o.active[id], sr = a.group === 'pilot' ? 1 : (cur.std ? cur.n / cur.std : 1), vr = cur.svcStd ? cur.svc / cur.svcStd : 1, fill = c.wStaff * sr + c.wSvc * vr;
