        if (MG.crisis && MG.crisis.on(C)) { var wD = M.k * pp * (pp > 0 ? (100 - g.morale) / 40 : 1), cA = MG.crisis.staffAdd(C, gk), m0 = g.morale; dm += cA; }   // 1C-3a E11 ⑤: 위기 효과(사기 기여 — 일회성은 한 번)
