    if (k.seats) v.slf = k.pax / k.seats * 100;
    if (k.fl) { v.d15 = (k.d15 || 0) / k.fl * 100; v.a15 = k.ot / k.fl * 100; }
    if (plan) v.cnl = k.cnl / plan * 100;
