    O().bench.forEach(function (m) {
      if (v[m[0]] == null) return; var sm = samples(C, t, m[0]), better = sm.filter(function (x) { return m[3] > 0 ? x > v[m[0]] : x < v[m[0]]; }).length;
      rk[m[0]] = [better + 1, sm.length + comps + 1];
    });
