  /* ======================= 지리·바람(교육용) ======================= */
  function gc(a, b) { var p1 = a.lat * D2R, p2 = b.lat * D2R, dl = (b.lon - a.lon) * D2R, dp = p2 - p1; var h = Math.pow(Math.sin(dp / 2), 2) + Math.cos(p1) * Math.cos(p2) * Math.pow(Math.sin(dl / 2), 2); return 2 * RE * Math.asin(Math.min(1, Math.sqrt(h))); }
