  /* ======================= 중량·탑재 모델(항목 1·2 공용, mg_data_fleet.js 머리말) ======================= */
  function dowOf(T, cfg) { var s = cfg || T.seatsDefault; return T.dowBase + s.J * T.seatKg.J + s.W * T.seatKg.W + s.Y * T.seatKg.Y; }
