      var nm = disp ? disp[2] : type;
      [1, 2, 3, 4].forEach(function (i) { add(i, ITEM[i - 1], 'unknown', MG.M('world.feasibility.107', { nm: nm })); });
      add(5, ITEM[4], 'ok', MG.M('world.feasibility.106'));
      add(6, ITEM[5], 'unknown', MG.M('world.feasibility.105'));
      add(7, ITEM[6], 'unknown', MG.M('world.feasibility.104'));
