    var comp = {};
    M().compRoutes.forEach(function (r, i) {
      var cx = cityOf(r[1]), cy = cityOf(r[2]), od = odKey(cx, cy), cr = M().competitors[r[0]], ft = cr.fleet[r[3]], blk = blockEst(r[1], r[2]);
      (comp[r[0]] = comp[r[0]] || {});
      var R = comp[r[0]][od] || (comp[r[0]][od] = { od: od, legs: [] });
      R.legs.push({ id: r[0] + i, from: r[1], to: r[2], fleet: r[3], seats: ft.seats, block: blk, times: r[4].slice() });
    });
    S = { ods: ods, comp: comp };
