    Object.keys(out).forEach(function (od) { var o = out[od]; Object.keys(o).forEach(function (k) { if (k !== '_t') o[k] = o._t ? o[k] / o._t : null; }); });   // 항공 인원 0 → 미정(null, 반응 판단 건너뜀)
