      var ab = p.est && p.est.ab, cA = MG.canon(ad), use = ab ? (MG.canon(draftOf(ab.A.draft)) === cA ? 'A' : ab.B && MG.canon(draftOf(ab.B.draft)) === cA ? 'B' : null) : null, er = use && ab[use].months.filter(function (x) { return x.mk === mk; })[0];   // 승인된 계획 스냅샷과 같은 A/B 기안만(작업 기안과 구분)
      p.reports.push({ mk: mk, plan: plan, est: er ? { draft: use, flights: er.rFl, pax: er.rPax, measured: er.measured } : null, actual: { flights: fl, seats: cnt.seats, pax: pax, lf: cnt.seats ? Math.round(pax / cnt.seats * 1000) / 1000 : 0 }, od: { self: cnt.odSelf } });
