    Object.keys(D.mkt.comp).forEach(function (k) { Object.keys(D.mkt.comp[k].routes).forEach(function (od) { D.mkt.comp[k].routes[od].fareIdx = Math.round(D.mkt.comp[k].routes[od].fareIdx * X.compFare * 1000) / 1000; }); });
    D.pending = (D.pending || []).filter(function (q) { return q.kind === 'liq'; }); D.settings.autoStop =   // 1C-3b-2: 사본에 남은 유동성 카드는 사본 기본 행동(유예 none · 채권단 rehab)으로 결정 — 그 밖 결재함 비움(기존)
      { delay: false, month: false, proposal: false, cash: false, org: false };
    var segs = [{ reg: draft.reg, from: draft.from, rot: { base: draft.base, first: draft.first, slack: draft.slack, legs: MG.clone(draft.legs) } }];
    if (draft.dow && draft.dow.length < 7) segs[0].rot.dow = draft.dow.slice();   // 주간 운항 계약 v3 5: A/B = 같은 개정 경로
    var plan = { v: -1, kind: 'ops', title: 'A/B', segs: segs, rp: p.id }, why = MG.skd.preCheck(D, plan);
    if (why.length) return { ok: false, why: MG.M('_j', { xs: why, s: ' · ' }) };
    var legs0 = D.slot && MG.slot ? D.legs.map(function (L) { return MG.clone(L); }) : null, r = MG.ops.revise(D, plan, { noPend: true, by: 'ab' });
    var slotAssume = null;
