  function resAt(C, sid, d) { return ix(C).res[sid + '|' + d] || null; }

  /* ---------- 시리즈 만들기 ---------- */
  // F1 시리즈 최소 횟수(같은 시각·같은 요일 · 같은 시즌 규칙 배정): 하계 NS27부터 7 · 동계·그 이전 5 — 데이터 slotApp.seriesMin(null = F1 끔 — 호환 차분 시험용)
  function minSeries(sid) { var m = AP().seriesMin; if (!m) return 0; return sid[1] === 'S' && +sid.slice(2) >= m.sFrom ? m.S : m.W; }
  function mk(C, o) {   // 새 시리즈 — 색인은 다음 조회 때 다시 계산(bump)
    var id = 'S' + (++S(C).seq.s), dates = o.dates.slice().sort(), occ = {};
    dates.forEach(function (d) { occ[d] = 'p'; });
    S(C).series[id] = { id: id, apt: o.apt, season: o.season, dir: o.dir, dow: o.dow, hm: o.hm, dates: dates, assigned: dates.length, operated: 0, unusedJ: 0, unusedO: 0, occ: occ, pc: {},
      historic: o.historic, added: !!o.added, spare: !!o.spare, state: 'held', lateReturns: 0, note: o.note || null, src: o.src, t: C.t };
    var mn = minSeries(o.season); if (mn && dates.length < mn && !/^(migrate|succ:)/.test(o.src || '')) S(C).series[id].adhoc = true;   // F1(WASG 3판 부속 12.1): 최초 배정 횟수 < 최소(하계 S27~ 7 · 그 밖 5) = 임시 배정 — 역사적 우선권 대상 아님(이전·승계분 = 이미 보유한 시리즈 제외)
    bump(C); return id;
  }

  /* ---------- 편 → 이착륙(레벨 3만): [공항, 방향, 현지 날짜, 현지 분] ---------- */
  function movesOfFlight(f) {
    var out = [];
    if (lvl(f.from) === 3) { var a = MG.tz.local(f.std, tzOf(f.from)); out.push([f.from, 'D', a.date, a.hm]); }
    if (lvl(f.to) === 3) { var b = MG.tz.local(f.sta, tzOf(f.to)); out.push([f.to, 'A', b.date, b.hm]); }
    return out;
  }
  // leg → 회전일 기준 이착륙 오프셋(같은 leg는 날짜가 바뀌어도 같음 — 아시아 DST 없음 · DST 공항은 그날 다시 계산)
  function legMoves(C, L) {
    var B = MG.data.base, ref = L.validFrom, out = [];
    var dep = MG.tz.toUTC(add(ref, L.dayOffset), L.stdLocal, B.airports[L.from].tz); if (dep.hold) return out;
    var a = MG.tz.local(dep.t, tzOf(L.from)), b = MG.tz.local(dep.t + L.block, tzOf(L.to)), dd = function (x) { return Math.round((Date.parse(x) - Date.parse(ref)) / 86400000); };
    if (lvl(L.from) === 3) out.push([L.from, 'D', dd(a.date), a.hm]);
    if (lvl(L.to) === 3) out.push([L.to, 'A', dd(b.date), b.hm]);
    return out;
  }
  function seasonsWithSeries(C) { var m = {}; Object.keys(S(C).series).forEach(function (id) { m[S(C).series[id].season] = 1; }); return Object.keys(m).sort(function (a, b) { return sInfo(a).start < sInfo(b).start ? -1 : 1; }); }
  function horizonEnd(C) { var ss = seasonsWithSeries(C); return ss.length ? sInfo(ss[ss.length - 1]).end : today(C); }

  /* ---------- 이전(6-1 · 키 slot:migrate) ---------- */
  function init(C) { if (C.cal === '30d' || !MG.world || !C.net) { C.slot = null; return; } if (!C.slot) migrate(C); }
  function restore(C) { if (!C.slot && C.cal !== '30d' && MG.world && C.net && C.legs && C.legs.length) migrate(C); }
  function migrate(C) {
    var td = today(C), cur = seasonOf(td), nxt = nextSeason(cur);
    C.slot = { rule: 1, series: {}, spareDaily: {}, apps: {}, seq: { s: 0, a: 0, r: 0 }, hbd: {}, tries: {}, hold: {}, holdApp: {}, holdSup: {}, gap: {}, lateRet: {}, warn: {}, l2: {}, mig: { at: td, chk: {} }, ixv: 0 };
    var freqTails = {}; ((C.net && C.net.freq) || []).forEach(function (q) { if (q && q.tail) freqTails[q.tail] = 1; });
    [cur, nxt].forEach(function (sid) {
      var si = sInfo(sid), keyN = {};                   // (공항·방향·요일·분·added) → 그 시즌 날짜별 필요 개수
      var d1 = td > si.start ? td : si.start, cnt = {};   // 날짜(현지)·공항·방향·시각(그날 실제 STD/STA — movesOn)·증편 여부 → 편 수
      C.legs.forEach(function (L) {
        var a = L.validFrom > add(d1, -3) ? L.validFrom : add(d1, -3), b = L.validTo && L.validTo < si.end ? L.validTo : si.end;
        for (var r0 = a; r0 <= b; r0 = add(r0, 1)) movesOn(L, r0).forEach(function (v) { if (v[2] < d1 || v[2] > si.end) return; var k = v[2] + '|' + v[0] + '|' + v[1] + '|' + v[3] + '|' + (freqTails[L.tail] ? 1 : 0); cnt[k] = (cnt[k] || 0) + 1; });
      });
      Object.keys(cnt).sort().forEach(function (k) { var p = k.split('|'), d = p[0], kk = p[1] + '|' + p[2] + '|' + p[3] + '|' + p[4] + '|' + dowOf(d), arr = keyN[kk] || (keyN[kk] = []); for (var i = 0; i < cnt[k]; i++) (arr[i] = arr[i] || []).push(d); });
      Object.keys(keyN).sort().forEach(function (kk) {
        var p = kk.split('|');
        keyN[kk].forEach(function (dates) { mk(C, { apt: p[0], season: sid, dir: p[1], dow: +p[4], hm: +p[2], dates: dates, historic: true, added: p[3] === '1', note: 'migrated-assumed', src: 'migrate' }); });
      });
    });
    Object.keys(W().slotSpare).forEach(function (a) { if (lvl(a) === 3) S(C).spareDaily[a] = Math.max(0, (C.net.slotSpare[a] || 0) - (C.net.slotUsedBy[a] || 0)); });
    [cur, nxt].forEach(function (sid) { var si = sInfo(sid); if (si.hbd < td) S(C).hbd[sid] = { at: si.hbd, ids: idsOf(C, sid), assumed: true }; });   // 캠페인 전 HBD = 이전 시리즈를 기준 보유분으로 가정
    // 연결표 검산(오늘): 공항마다 이전 전 「하루 이착륙(slotUse) + 여유(slotFree)」 = 이전 후 「오늘 유효 시리즈 수 + spareDaily」
    Object.keys(S(C).spareDaily).forEach(function (a) { S(C).mig.chk[a] = { before: (MG.world.slotUse(C, a) || 0) + MG.world.slotFreeRaw(C, a), series: activeOn(C, a, td), spare: S(C).spareDaily[a] }; });
    MG.ledger.mark(C, 'slot:migrate');
    [cur, nxt].forEach(function (sid) { sched(C, sid); });
    reserveAll(C);
    log(C, MG.M('slot.migrate.1', { length: Object.keys(S(C).series).length, spareDaily: JSON.stringify(S(C).spareDaily) }));
  }
  function idsOf(C, sid) { return Object.keys(S(C).series).filter(function (id) { var s = S(C).series[id]; return s.season === sid && s.state === 'held' && s.assigned > 0; }); }
  function activeOn(C, a, d) { var n = 0; Object.keys(S(C).series).forEach(function (id) { var s = S(C).series[id]; if (s.apt === a && s.occ[d] && s.occ[d] !== 'r' && s.occ[d] !== 'x') n++; }); return n; }
  function sched(C, sid) {                         // 시즌 사건: HBD(기준 동결) · 시작(전환) · evalDate(판정)
    var si = sInfo(sid), td = today(C);
    [['hbd', si.hbd, 2], ['open', si.start, 2], ['eval', si.eval, 8]].forEach(function (x) {
      var key = 'slot:' + sid + ':' + x[0]; if (x[1] < td || C.keys[key] || C.queue.some(function (q) { return q.key === key; })) return;
      C.queue.push({ t: MG.tz.dayStart(x[1], C.hqTz), prio: x[2], key: key, kind: 'slot-' + x[0], season: sid });
    });
  }

  /* ---------- 편 예약(occurrence 1개 = 편 1개 · 중복 0) ---------- */
  function reserve(C, f) { if (!on(C)) return; var X = ix(C); if (X.fk[f.id] || !movesOfFlight(f).length) { if (!X.fk[f.id]) X.fk[f.id] = {}; } regroup(C, f, true); }
  function reserveAll(C) { if (!on(C)) return; bump(C); ix(C); }
  function resOf(C, f) { return on(C) ? (ix(C).fk[f.id] || {}) : {}; }
  function release(C, f) { if (!on(C)) return; regroup(C, f, false); }
  // ④ 운항 허용: 레벨 3 출발·도착 occurrence가 없으면 출발 불가(1A-1 출발 검사 · hardBlock)
  function missing(C, f) {
    if (!on(C)) return null; reserve(C, f); var r = resOf(C, f), out = [];
    movesOfFlight(f).forEach(function (m) { if (!r[m[1]]) out.push(MG.M('slot.missing.4', { v: m[0], v2: m[1] === 'D' ? MG.M('slot.missing.3') : MG.M('slot.missing.2'), v3: m[2], v4: MG.tz.hmStr(m[3]) })); });
    return out.length ? MG.M('slot.missing.1', { out: out }) : null;
  }
  function setOcc(C, s, d, ch) {
    var o = s.occ[d]; if (o === ch || o === 'o' || o === 'j' || o === 'x' || o === 'r') return false;   // 최종 결과는 한 번만
    s.occ[d] = ch; if (ch === 'o') s.operated++; else if (ch === 'j') s.unusedJ++; else if (ch === 'x') s.unusedO++; return true;
  }
  function opDir(C, f, dir, ch, cause) {           // 그 방향 occurrence 확정(운항 o / 결항 w) — 확정 전 대응으로 찾고, 확정 뒤 그 묶음 다시 맞춤
    // 128차(E6 시험 중 발견): 색인은 저장 밖이라 저장 재개·bump 뒤 첫 조회 때 다시 만든다 — 그 첫 조회가 바로 이 확정(AIBT·AOBT를 이미 적은 뒤)이면
    //   이 편이 운항 전이 아니어서 대응에서 빠지고 occurrence가 운항으로 남지 않았다. onCancel과 같은 방식으로, 대응을 찾는 동안만 그 방향 실적 시각을 비운다(이미 있는 색인이면 결과 동일)
    var fld = dir === 'D' ? 'aobt' : 'aibt', v0 = f[fld]; f[fld] = null; var r = MG.clone(resOf(C, f)); f[fld] = v0;
    var X = ix(C);
    movesOfFlight(f).forEach(function (m) { if (m[1] !== dir) return; var s = r[dir] && S(C).series[r[dir]]; if (s && setOcc(C, s, m[2], ch) && cause) s.pc[m[2]] = cause; match(C, X, m[0] + '|' + m[1] + '|' + m[2]); });
  }
