    if (x.m === 'op') s.push(MG.M('fleet.card.13', { pmt: x.pmt, n: x.n, dep: x.dep, mxr: x.mxr, v: Math.round(x.mxrRf * 100), check: x.check }));
    else if (x.m === 'fin') s.push(MG.M('fleet.card.12', { pmt: x.pmt, n: x.n, price: x.price, v: Math.round(x.rate * 12 * 1000) / 10, dep: x.dep, opt: x.opt, mxr: x.mxr }));
    else s.push(MG.M('fleet.card.11', { price: x.price, pdp: x.pdp, bal: x.bal, v: x.loan ? MG.M('fleet.card.10', { loan: x.loan, loanPmt: x.loanPmt, loanN: x.loanN, v: Math.round(x.loanRate * 12 * 1000) / 10 }) : '', depN: x.depN, v2: Math.round(x.resid * 100) }));
