    if (!A) {
      A = L.arrears[k] = { obl: o.id, no: I.no, kind: o.kind, due: I.due, prin: q.prin, int: q.int, amt: q.prin + q.int, firstFail: d, state: 'open', late: 0, prio: prioOf(o) }; nw = true;
      xlog(C, 'fail', k); log(C, MG.M('liq.fail.2', { label: o.label, total: q.total, v: C.bal.cash || 0 }));
    } else A.lastTry = d;
