    var tot = 0, byRoute = {}; rots.forEach(function (x) { tot += x.legs.length; var rk = x.route || x.reg; byRoute[rk] = (byRoute[rk] || 0) + x.legs.length; });
    var baseW = weekLegs(C, from), base = baseW / 7, uw = patAt(C, from); tot = base;   // N152-01: 목표 분모 = 기준일 회사 전체 운항 계획 편수(B) — 후보 적격(line·예약)은 어떤 기체를 줄일지의 제약으로만
    var target = tgtDay(baseW), targetW = 7 * target, seen = {};
