      var cx = L + bw * i + bw / 2; x.fillStyle = '#8191b0'; if (v.length < 16 || i % 2 === 0) x.fillText(MG.T.s(lab[i]), cx - 7, Hh - 5);
      if (kind !== 'line') { var y0 = ys(0), y1 = ys(q); x.fillStyle = kind === 'bar±' ? (q < 0 ? '#ff5c6c' : col) : col; x.fillRect(cx - bw * .32, Math.min(y0, y1), bw * .64, Math.abs(y1 - y0)); }
