    cv.onclick = function (e) { var rr = cv.getBoundingClientRect(), px = e.clientX - rr.left, h2 = cv._hit.filter(function (q) { return px >= q[0] && px < q[1]; })[0]; if (h2) meeting(null, h2[2]); };
