    on('rpNew', function () { var spec = form(), T = C().tails[spec.reg], bw = baseWarn(C(), spec.reg, spec.from) || dlvWarn(C(), spec.reg, spec.eff); V.form = spec; if ((T && T.status === 'line') || bw) { V.warn = { reg: spec.reg, line: !!(T && T.status === 'line'), bw: bw, rots: rotsOf(C(), spec.reg, spec.eff || today(C())), spec: spec }; render(); return; } mk(spec); });
