    Array.prototype.forEach.call(document.querySelectorAll('#m_rp [data-goorg]'), function (b) { b.onclick = function () { if (MG.uiOrg && MG.uiOrg.open) MG.uiOrg.open(b.dataset.goorg, b.dataset.dept || null); H.go('org'); }; });
    on('rdAfterDlv', function () { var e = $('rdFrom'), v = $('rdAfterDlv').dataset.v; if (e) { e.value = v; e.scrollIntoView({ block: 'center' }); e.focus(); } });
    on('rdSalesFill', function () { var e = $('rdSales'), v = $('rdSalesFill').dataset.v; if (e) { e.value = v; e.scrollIntoView({ block: 'center' }); e.focus(); } });
