    on('rpFinal', function () { act(function (c) { return MG.rp.requestFinal(c, id, 'player'); }, MG.T.s(id) + ' 최종 투자 승인 품의(결재함)'); });
    on('rpSales', function () { act(function (c) { return MG.rp.approveSales(c, id, 'player'); }, MG.T.s(id) + ' 판매 준비 승인'); });
