    if (v.ok) { var r = MG.org.newFromScenario(v.S, { id: 'vela-main', b: !!(MG.board && MG.board.ui) }); if (r.ok) { var c = r.C; out.ch = MG.org.challenge(c); out.elig = !!c.scenario.scoreEligible; out.s0 = c.scenario.settings0 || null; out.goals = c.ach ? c.ach.goals : null; out.dp = c.crisis.p; } }
